// The production SPV code bundled for tests with the anchor table cut to its first 25 entries (newest 131,071), so no
// release checkpoint lies above the newest entry, as with the release table in production. With `powList`, the
// bundle's proof-of-work check also accepts a header whose hash is in `globalThis.__testPowOk`: chains generated by a
// test (real links, times and LWMA bits, no mining) then verify. Both replacements exist only in this test bundle; the
// shipped src/ and its vendored bundle are not changed.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";
import { SEAL_ANCHORS, SEAL_NEWEST } from "./spvfixture.mjs";

const root = fileURLToPath(new URL("../..", import.meta.url));

function once(src, find, replace, what) {
  const n = src.split(find).length - 1;
  if (n !== 1) throw new Error(`${what}: the text to replace occurs ${n} times`);
  return src.replace(find, replace);
}

/** Imports `exports` (an ES export statement over paths from the repo root) from a bundle with the cut table. */
export async function cutTableBundle(exports, { powList = false } = {}) {
  const anchorsSrc = readFileSync(`${root}/src/core/spvanchors.ts`, "utf8");
  const cut = anchorsSrc.replace(/export const SPV_ANCHORS: readonly string\[\] = \[[\s\S]*?\];/, (m) => {
    const entries = [...m.matchAll(/"0x[0-9a-f]{64}"/g)].map((x) => x[0]).slice(0, SEAL_ANCHORS.length);
    return `export const SPV_ANCHORS: readonly string[] = [${entries.join(", ")}];`;
  });
  if (cut === anchorsSrc) throw new Error("the anchor table was not cut");
  const vendor = powList
    ? once(readFileSync(`${root}/src/vendor/cairnx-spv.js`, "utf8"), "function powOkMemo(headerHashBE, bits) {\n",
      "function powOkMemo(headerHashBE, bits) {\n  if (globalThis.__testPowOk?.has(hx(headerHashBE))) { const t = bitsToTargetBigInt(bits); return !(t === 0n || t > POW_LIMIT_TARGET2); }\n",
      "the proof-of-work list")
    : null;
  const text = (await build({
    stdin: { contents: exports, resolveDir: root, loader: "ts" },
    bundle: true, format: "esm", platform: "node", target: "es2022", write: false, logLevel: "warning",
    plugins: [{ name: "cut-table", setup(b) {
      b.onLoad({ filter: /spvanchors\.ts$/ }, () => ({ contents: cut, loader: "ts" }));
      b.onLoad({ filter: /spvnewest\.ts$/ }, () => ({ contents: `export const SPV_NEWEST_HEIGHT = ${SEAL_NEWEST};`, loader: "ts" }));
      if (vendor) b.onLoad({ filter: /cairnx-spv\.js$/ }, () => ({ contents: vendor, loader: "js" }));
    } }],
  })).outputFiles[0].text;
  return import(`data:text/javascript;base64,${Buffer.from(text).toString("base64")}`);
}
